from solution import text_match_two_three


def test_issue_example_ac_not_matched():
    """Issue: example 'text_match_two_three("ac")==('Not matched!')'."""
    assert text_match_two_three("ac") == "Not matched!"  # 0*'b' after 'a': 0 not in [2,3] => no match


def test_issue_two_bs_minimum_match():
    """Issue: 'an a followed by two to three b' includes exactly 2 b's."""
    assert text_match_two_three("abb") == "Found a match!"  # 'a'+2*'b': 2 in [2,3] => match


def test_issue_three_bs_maximum_match():
    """Issue: 'an a followed by two to three b' includes exactly 3 b's."""
    assert text_match_two_three("abbb") == "Found a match!"  # 'a'+3*'b': 3 in [2,3] => match


def test_issue_one_b_below_minimum():
    """Issue: 'an a followed by two to three b' excludes only 1 b."""
    assert text_match_two_three("ab") == "Not matched!"  # 'a'+1*'b': 1 not in [2,3] => no match


def test_issue_four_bs_still_contains_match():
    """Issue: 'has an a followed by two to three b' matches substring in 'abbbb'."""
    assert text_match_two_three("abbbb") == "Found a match!"  # 4*'b' contains first 3*'b': 3 in [2,3] => match


def test_issue_empty_string_not_matched():
    """Issue: 'an a followed by two to three b' is absent from empty string."""
    assert text_match_two_three("") == "Not matched!"  # length 0: 0 not in [2,3] => no match


def test_issue_embedded_match_in_longer_string():
    """Issue: 'has an a followed by two to three b' means substring search."""
    assert text_match_two_three("xxabbxx") == "Found a match!"  # contains 'a'+2*'b': 2 in [2,3] => match


def test_issue_bbs_without_a_not_matched():
    """Issue: 'an a followed by two to three b' requires the leading a."""
    assert text_match_two_three("bbb") == "Not matched!"  # 3*'b' with 0*'a': missing 'a' => no match


def test_issue_lone_a_not_matched():
    """Issue: 'an a followed by two to three b' requires 2-3 b's after a."""
    assert text_match_two_three("a") == "Not matched!"  # 'a'+0*'b': 0 not in [2,3] => no match


def test_contract_keyword_text_parameter():
    """Contract: 'def text_match_two_three(text)' takes parameter named text."""
    assert text_match_two_three(text="ac") == "Not matched!"  # 1 kwarg named text: 1==1 => binds


def test_contract_result_is_string():
    """Contract: return value is a string as shown by 'Not matched!' example."""
    assert isinstance(text_match_two_three("abb"), str)  # 1 return value: 1==1 => is str
